python3 << 'EOF'
import zipfile
import xml.etree.ElementTree as ET

NS = {'m': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main',
      'r': 'http://schemas.openxmlformats.org/officeDocument/2006/relationships'}

z = zipfile.ZipFile('budget.xlsx')
wb = ET.fromstring(z.read('xl/workbook.xml'))
sheets = [(s.attrib['name'], s.attrib.get('{%s}id' % NS['r'])) for s in wb.find('m:sheets', NS)]

shared = []
if 'xl/sharedStrings.xml' in z.namelist():
    ss = ET.fromstring(z.read('xl/sharedStrings.xml'))
    for si in ss.findall('m:si', NS):
        shared.append(''.join(t.text or '' for t in si.iter('{%s}t' % NS['m'])))

rels = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
rid2target = {r.attrib['Id']: r.attrib['Target'] for r in rels}

for name, rid in sheets:
    target = rid2target.get(rid, '')
    if target and not target.startswith('/'):
        target = 'xl/' + target
    print(f'=== Sheet: {name} ({target}) ===')
    if target not in z.namelist():
        print('  <missing>')
        continue
    root = ET.fromstring(z.read(target))
    for row in root.find('m:sheetData', NS).findall('m:row', NS):
        cells = []
        for c in row.findall('m:c', NS):
            ref = c.attrib.get('r', '')
            t = c.attrib.get('t', 'n')
            v = c.find('m:v', NS)
            val = ''
            if v is not None:
                if t == 's':
                    val = shared[int(v.text)]
                elif t in ('str', 'inlineStr'):
                    val = v.text or ''
                else:
                    val = v.text
            cells.append(f'{ref}={val!r}')
        print(' | '.join(cells))
    print()
EOF

